128→  private loadOrCreateSecret(): void {
129→    const dir = path.dirname(this.secretFilePath)
130→    fs.mkdirSync(dir, { recursive: true })
131→
132→    try {
133→      this.secret = fs.readFileSync(this.secretFilePath, 'utf-8').trim()
134→      if (this.secret) {
135→        // Warn if file permissions are too open (like SSH does for private keys)
