141→          }
142→        } catch { /* stat failed, skip check */ }
143→        return
144→      }
145→    } catch {
146→      // File doesn't exist, create it
147→    }
148→
149→    this.secret = crypto.randomBytes(32).toString('hex')
150→    fs.writeFileSync(this.secretFilePath, this.secret, { mode: 0o600 })
