153→  private authenticate(req: http.IncomingMessage): boolean {
154→    const authHeader = req.headers.authorization
155→    if (!authHeader?.startsWith('Bearer ')) return false
156→    const token = authHeader.slice(7)
157→    if (token.length !== this.secret.length) return false
158→    return crypto.timingSafeEqual(Buffer.from(token, 'utf-8'), Buffer.from(this.secret, 'utf-8'))
159→  }
