161→  private async handleRequest(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
162→    const method = req.method?.toUpperCase()
163→    const url = req.url || ''
164→
165→    const isExempt = (method === 'GET' && (url === '/api/health' || url === '/api/version'))
166→    if (!isExempt && !this.authenticate(req)) {
167→      this.sendJson(res, 401, { error: 'Unauthorized' })
168→      return
169→    }
170→
171→    try {
172→      if (method === 'POST' && url === '/api/sessions/adopt') {
173→        await this.handleAdoptSession(req, res)
174→      } else if (method === 'POST' && url === '/api/sessions') {
175→        await this.handleCreateSession(req, res)
176→      } else if (method === 'POST' && url.match(/^\/api\/sessions\/([^/]+)\/prompt$/)) {
177→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)\/prompt$/)![1])
178→        await this.handleSendPrompt(sessionId, req, res)
179→      } else if (method === 'PATCH' && url.match(/^\/api\/sessions\/([^/]+)\/dangerous$/)) {
180→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)\/dangerous$/)![1])
181→        await this.handleToggleDangerous(sessionId, req, res)
182→      } else if (method === 'GET' && url.match(/^\/api\/sessions\/([^/]+)$/)) {
183→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)$/)![1])
184→        await this.handleGetSession(sessionId, res)
185→      } else if (method === 'DELETE' && url.match(/^\/api\/sessions\/([^/]+)$/)) {
186→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)$/)![1])
187→        await this.handleCancelSession(sessionId, res)
188→      } else if (method === 'GET' && url === '/api/sessions') {
189→        await this.handleListSessions(res)
190→      } else if (method === 'GET' && url === '/api/agents') {
191→        await this.handleListAgents(res)
192→      } else if (method === 'GET' && url === '/api/health') {
193→        await this.handleHealth(res)
194→      } else if (method === 'GET' && url === '/api/version') {
195→        await this.handleVersion(res)
196→      } else if (method === 'GET' && url === '/api/config/editable') {
197→        await this.handleGetEditableConfig(res)
198→      } else if (method === 'GET' && url === '/api/config') {
199→        await this.handleGetConfig(res)
200→      } else if (method === 'PATCH' && url === '/api/config') {
201→        await this.handleUpdateConfig(req, res)
202→      } else if (method === 'GET' && url === '/api/adapters') {
203→        await this.handleListAdapters(res)
204→      } else if (method === 'GET' && url === '/api/tunnel') {
205→        await this.handleTunnelStatus(res)
206→      } else if (method === 'POST' && url === '/api/notify') {
207→        await this.handleNotify(req, res)
208→      } else if (method === 'POST' && url === '/api/restart') {
209→        await this.handleRestart(res)
210→      } else if (method === 'GET' && url.match(/^\/api\/topics(\?.*)?$/)) {
211→        await this.handleListTopics(url, res)
212→      } else if (method === 'POST' && url === '/api/topics/cleanup') {
213→        await this.handleCleanupTopics(req, res)
214→      } else if (method === 'DELETE' && url.match(/^\/api\/topics\/([^/?]+)/)) {
215→        const match = url.match(/^\/api\/topics\/([^/?]+)/)!
216→        await this.handleDeleteTopic(decodeURIComponent(match[1]), url, res)
217→      } else {
218→        this.sendJson(res, 404, { error: 'Not found' })
219→      }
220→    } catch (err) {
221→      log.error({ err }, 'API request error')
222→      this.sendJson(res, 500, { error: 'Internal server error' })
223→    }
224→  }
