226→  private async handleCreateSession(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
227→    const body = await this.readBody(req)
228→    let agent: string | undefined
229→    let workspace: string | undefined
230→
231→    if (body) {
232→      try {
233→        const parsed = JSON.parse(body)
234→        agent = parsed.agent
235→        workspace = parsed.workspace
236→      } catch {
237→        this.sendJson(res, 400, { error: 'Invalid JSON body' })
238→        return
239→      }
240→    }
241→
242→    // Check max concurrent sessions
243→    const config = this.core.configManager.get()
244→    const activeSessions = this.core.sessionManager.listSessions()
245→      .filter(s => s.status === 'active' || s.status === 'initializing')
246→    if (activeSessions.length >= config.security.maxConcurrentSessions) {
247→      this.sendJson(res, 429, {
248→        error: `Max concurrent sessions (${config.security.maxConcurrentSessions}) reached. Cancel a session first.`,
249→      })
250→      return
251→    }
252→
253→    // Use the first registered adapter (e.g. Telegram) so API sessions appear in the channel
254→    const [adapterId, adapter] = this.core.adapters.entries().next().value ?? [null, null]
255→    const channelId = adapterId ?? 'api'
256→
257→    const resolvedAgent = agent || config.defaultAgent
258→    const resolvedWorkspace = this.core.configManager.resolveWorkspace(
259→      workspace || config.agents[resolvedAgent]?.workingDirectory,
260→    )
261→
262→    const session = await this.core.createSession({
263→      channelId,
264→      agentName: resolvedAgent,
265→      workingDirectory: resolvedWorkspace,
266→      createThread: !!adapter,
267→      initialName: `🔄 ${resolvedAgent} — New Session`,
268→    })
269→
270→    // If no adapter wired events (headless), auto-approve permissions
271→    if (!adapter) {
272→      session.agentInstance.onPermissionRequest = async (request) => {
273→        const allowOption = request.options.find(o => o.isAllow)
274→        log.debug({ sessionId: session.id, permissionId: request.id, option: allowOption?.id }, 'Auto-approving permission for API session')
275→        return allowOption?.id ?? request.options[0]?.id ?? ''
276→      }
277→    }
278→
279→    // Warmup in background so session moves from 'initializing' to 'active'
280→    session.warmup().catch(err => log.warn({ err, sessionId: session.id }, 'API session warmup failed'))
281→
282→    this.sendJson(res, 200, {
283→      sessionId: session.id,
284→      agent: session.agentName,
285→      status: session.status,
286→      workspace: session.workingDirectory,
287→    })
288→  }
