290→  private async handleSendPrompt(sessionId: string, req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
291→    const session = this.core.sessionManager.getSession(sessionId)
292→    if (!session) {
293→      this.sendJson(res, 404, { error: `Session "${sessionId}" not found` })
294→      return
295→    }
296→
297→    if (session.status === 'cancelled' || session.status === 'finished' || session.status === 'error') {
298→      this.sendJson(res, 400, { error: `Session is ${session.status}` })
299→      return
300→    }
301→
302→    const body = await this.readBody(req)
303→    let prompt: string | undefined
304→    if (body) {
305→      try {
306→        const parsed = JSON.parse(body)
307→        prompt = parsed.prompt
308→      } catch {
309→        this.sendJson(res, 400, { error: 'Invalid JSON body' })
310→        return
311→      }
312→    }
313→
314→    if (!prompt) {
315→      this.sendJson(res, 400, { error: 'Missing prompt' })
316→      return
317→    }
318→
319→    session.enqueuePrompt(prompt).catch(() => {})
320→    this.sendJson(res, 200, { ok: true, sessionId, queueDepth: session.queueDepth })
321→  }
