428→  private async handleUpdateConfig(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
429→    const body = await this.readBody(req)
430→    let configPath: string | undefined
431→    let value: unknown
432→
433→    if (body) {
434→      try {
435→        const parsed = JSON.parse(body)
436→        configPath = parsed.path
437→        value = parsed.value
438→      } catch {
439→        this.sendJson(res, 400, { error: 'Invalid JSON body' })
440→        return
441→      }
442→    }
443→
444→    if (!configPath) {
445→      this.sendJson(res, 400, { error: 'Missing path' })
446→      return
447→    }
448→
449→    // Pre-validate by cloning config and applying the change
450→    const currentConfig = this.core.configManager.get()
451→    const cloned = structuredClone(currentConfig) as Record<string, unknown>
452→    const parts = configPath.split('.')
453→    let target: Record<string, unknown> = cloned
454→    for (let i = 0; i < parts.length - 1; i++) {
455→      if (target[parts[i]] && typeof target[parts[i]] === 'object' && !Array.isArray(target[parts[i]])) {
456→        target = target[parts[i]] as Record<string, unknown>
457→      } else {
458→        this.sendJson(res, 400, { error: 'Invalid config path' })
459→        return
460→      }
461→    }
462→
463→    const lastKey = parts[parts.length - 1]
464→    if (!(lastKey in target)) {
465→      this.sendJson(res, 400, { error: 'Invalid config path' })
466→      return
467→    }
468→
469→    target[lastKey] = value
470→
471→    // Validate with Zod
472→    const { ConfigSchema } = await import('./config.js')
473→    const result = ConfigSchema.safeParse(cloned)
474→    if (!result.success) {
475→      this.sendJson(res, 400, {
476→        error: 'Validation failed',
477→        details: result.error.issues.map(i => ({ path: i.path.join('.'), message: i.message })),
478→      })
479→      return
480→    }
481→
482→    // Convert dot-path to nested object for save
483→    const updates: Record<string, unknown> = {}
484→    let updateTarget = updates
485→    for (let i = 0; i < parts.length - 1; i++) {
486→      updateTarget[parts[i]] = {}
487→      updateTarget = updateTarget[parts[i]] as Record<string, unknown>
488→    }
489→    updateTarget[lastKey] = value
490→
491→    await this.core.configManager.save(updates, configPath)
492→
493→    const { isHotReloadable } = await import('./config-registry.js')
494→    const needsRestart = !isHotReloadable(configPath!)
495→
496→    this.sendJson(res, 200, {
497→      ok: true,
498→      needsRestart,
499→      config: redactConfig(this.core.configManager.get()),
500→    })
501→  }
